import functools
from neo4j import GraphDatabase, Transaction, TransactionError

def unit_of_work(metadata=None, timeout=None):
    def decorator(func):
        @functools.wraps(func)
        def decorated(tx: Transaction, *args, **kwargs):
            tx.config._config['metadata'] = metadata
            if timeout is not None:
                tx.config._config['timeout'] = timeout
            try:
                result = func(tx, *args, **kwargs)
                tx.success()
                return result
            except TransactionError as e:
                tx.failure()
                raise e
        return decorated
    return decorator

# Example usage:
@unit_of_work(timeout=100)
def count_people_tx(tx):
    result = tx.run("MATCH (a:Person) RETURN count(a) AS persons")
    record = result.single()
    return record["persons"]

# To run the example:
if __name__ == "__main__":
    uri = "bolt://localhost:7687"
    driver = GraphDatabase.driver(uri, auth=("neo4j", "password"))
    with driver.session() as session:
        people_count = session.write_transaction(count_people_tx)
        print(f"Number of people: {people_count}")
    driver.close()

