from functools import wraps
from collections import OrderedDict

def lfu_cache(maxsize=128, typed=False):
    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()
            self.frequency = {}
            self.size = 0

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = (func, args, tuple(kwargs.items())) if self.typed else (func, tuple(args), tuple(kwargs.items()))
                if key in self.cache:
                    self.frequency[key] += 1
                    val = self.cache.move_to_end(key, last=False)
                else:
                    val = func(*args, **kwargs)
                    self.cache[key] = val
                    self.frequency[key] = 1
                    self.size += 1
                    if self.size > self.maxsize:
                        self.evict()
                return val
            return wrapper

        def evict(self):
            if not self.cache:
                return
            # Find the key with the lowest frequency
            min_freq = min(self.frequency.values())
            for key, freq in self.frequency.items():
                if freq == min_freq:
                    self.cache.pop(key)
                    self.frequency.pop(key)
                    self.size -= 1
                    break

    return LFUCache(maxsize, typed)

