def _legacy_mergeOrderings(orderings):
    from collections import defaultdict

    def find(a, b):
        path = {}
        while a in path:
            a = path[a]
        while b in path:
            b = path[b]
        if a != b:
            path[a] = b

    def union(a, b):
        if a < b:
            path[b] = a
        else:
            path[a] = b

    starts = defaultdict(list)
    ends = defaultdict(list)
    for ordering in orderings:
        starts[ordering[0]].append(ordering)
        ends[ordering[-1]].append(ordering)

    path = {}
    component = 0

    for ordering in orderings:
        for obj in ordering:
            starts[obj].sort(key=ordering.index)
            ends[obj].sort(key=ordering.index)

    for ordering in orderings:
        for obj in ordering:
            if obj not in path:
                component += 1
                for start in starts[obj]:
                    for end in ends[obj]:
                        union(start[0], end[-1])

    result = []
    for ordering in orderings:
        if not result or result[-1] in path:
            result.extend(ordering)
        else:
            result.extend(ordering[ordering.index(path[result[-1]]) + 1:])

    return result

