def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_subclass(sub, base):
        return issubclass(sub, base) and sub is not base

    def minimal_baselist(baselist):
        minimal = []
        for base in baselist:
            if not any(is_subclass(base, m) for m in minimal):
                minimal.append(base)
        return minimal

    return minimal_baselist(classes)

# Example usage:
