import re
from typing import Any, AnyStr, Tuple, Union, Iterable, Dict, Sequence

class SQLParams:
    in_style = '?'

def formatmany(
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    if isinstance(sql, bytes):
        sql = sql.decode('utf-8')

    formatted_sql = sql
    out_params: List[Union[Dict[Union[str, int], Any], List[Sequence[Any]]]] = []

    for params in many_params:
        if isinstance(params, dict):
            out_param = {f':{i+1}': v for i, v in enumerate(params.values())}
        elif isinstance(params, sequence):
            out_param = params
        else:
            raise ValueError("params must be a Mapping or Sequence")

        formatted_sql = re.sub(r'\?', ':', formatted_sql, count=1)
        out_params.append(out_param)

    if isinstance(sql, bytes):
        formatted_sql = formatted_sql.encode('utf-8')

    return formatted_sql, out_params

