    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as file:
            content = file.read()
            for digest in digests_used:
                if digest not in content:
                    raise ValueError(f"Digest {digest} not found in {manifest_file}")
                if digests_used[digest] != content.count(digest):
                    raise ValueError(f"Digest {digest} used {content.count(digest)} times instead of {digests_used[digest]} times in {manifest_file}")

