def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(e):
        from sympy import And, Or, Not, simplify
        if isinstance(e, (And, Or)):
            if isinstance(e, And):
                if e.args[0] == e.args[1]:
                    return e.args[0]
                if isinstance(e.args[1], Or) and e.args[0] in e.args[1].args:
                    return e.args[0]
                if isinstance(e.args[0], Or) and e.args[1] in e.args[0].args:
                    return e.args[1]
            elif isinstance(e, Or):
                if e.args[0] == e.args[1]:
                    return e.args[0]
                if isinstance(e.args[1], And) and e.args[0] in e.args[1].args:
                    return e.args[0]
                if isinstance(e.args[0], And) and e.args[1] in e.args[0].args:
                    return e.args[1]
        return simplify(e)

    return [apply_absorption(arg) for arg in args]

