import datetime

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.strip()
    number, unit = frequency.split()

    try:
        number = int(number)
    except ValueError:
        raise ValueError("Invalid frequency number")

    if unit.lower() == "seconds":
        return datetime.timedelta(seconds=number)
    elif unit.lower() == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit.lower() == "hours":
        return datetime.timedelta(hours=number)
    elif unit.lower() == "days":
        return datetime.timedelta(days=number)
    elif unit.lower() == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit.lower() == "months":
        return datetime.timedelta(days=number * 30)  # Approximation
    elif unit.lower() == "years":
        return datetime.timedelta(days=number * 365)  # Approximation
    else:
        raise ValueError("Invalid frequency unit")

