from typing import List, Dict, Any, Tuple
import os

def load_configurations(config_filenames: List[str], overrides: Dict[str, Any] = None, resolve_env: bool = True) -> Tuple[Dict[str, Any], List[logging.LogRecord]]:
    logger = logging.getLogger(__name__)
    configs = {}
    error_logs = []

    def parse_config(filename: str) -> Any:
        try:
            with open(filename, 'r') as file:
                config_data = eval(file.read())
            if resolve_env:
                import os
                for key, value in config_data.items():
                    if isinstance(value, str) and value.startswith('${') and value.endswith('}'):
                        config_data[key] = os.getenv(value[2:-1], value)
            return config_data
        except Exception as e:
            error = logging.LogRecord(level=logging.ERROR, pathname=filename, lineno=0, levelname='ERROR', msg=f"Error parsing {filename}: {e}", args=())
            error_logs.append(error)
            return None

    for filename in config_filenames:
        config_data = parse_config(filename)
        if config_data is not None:
            configs[filename] = config_data

    if overrides:
        for key, value in overrides.items():
            if key in configs:
                configs[key].update(value)

    return configs, error_logs

