class Histogram:
    def __init__(self, data=None):
        self.data = data
        self._scale = None

    def compute_scale(self):
        if self.data is None:
            self._scale = 0
        else:
            self._scale = sum(self.data)

    def scale(self, other=None, recompute=False):
        if other is None:
            if self._scale is None and not recompute:
                self.compute_scale()
            return self._scale
        elif isinstance(other, float):
            if self._scale == 0:
                raise ValueError("Histogram scale is zero and cannot be rescaled")
            self.data = [x * (other / self._scale) for x in self.data]
            self.compute_scale()
        else:
            raise ValueError("Invalid value for 'other'")


# Example usage
