from collections import Counter

class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.usage_count = Counter()
        self.least_recently_used = []

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        self.update_usage(key)
        return self.cache[key]

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.cache:
            self.cache[key] = value
            self.update_usage(key)
            return
        if len(self.cache) >= self.capacity:
            self.evict()
        self.cache[key] = value
        self.usage_count[key] += 1
        self.least_recently_used.append(key)

    def update_usage(self, key: int) -> None:
        self.usage_count[key] += 1
        while self.least_recently_used and self.usage_count[self.least_recently_used[-1]] > self.usage_count[key]:
            self.least_recently_used.pop()
        self.least_recently_used.append(key)

    def evict(self) -> None:
        if not self.least_recently_used:
            return
        least_freq_key = self.least_recently_used[0]
        for key in self.least_recently_used:
            if self.usage_count[key] < self.usage_count[least_freq_key]:
                least_freq_key = key
            elif self.usage_count[key] == self.usage_count[least_freq_key]:
                if key not in self.least_recently_used[-1:None:-1]:
                    least_freq_key = key
        del self.cache[least_freq_key]
        del self.usage_count[least_freq_key]
        self.least_recently_used.remove(least_freq_key)

